import '../models/recipe.dart';
import '../models/ingredient.dart';
import 'ingredients_data.dart';

final Map<String, Ingredient> _ingMap = {
  for (var ing in IngredientsData.ingredients) ing.id: ing
};

List<Ingredient> _getIngredients(List<String> ids) {
  return ids
      .map((id) => _ingMap[id])
      .where((ing) => ing != null)
      .cast<Ingredient>()
      .toList();
}

