  Recipe(
    id: 'r_270',
    title: 'Patlıcanlı Kahvaltılık Sos',
    category: 'Sebze Yemekleri',
    emoji: '🥘',
    prepTimeMinutes: 65,
    difficultyStars: 3,
    calories: 432,
